"use client";
/* Card, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Card(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("card"); }, []);
  return React.createElement("piix-card", piixAttrs(props));
}

export default Card;
